CREATE TABLE IF NOT EXISTS expense_categories(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,society_id BIGINT UNSIGNED NOT NULL,name VARCHAR(120) NOT NULL,description VARCHAR(300) NULL,status ENUM('ACTIVE','INACTIVE') NOT NULL DEFAULT 'ACTIVE',created_by BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,deleted_at TIMESTAMP NULL,UNIQUE KEY uk_expense_category(society_id,name),CONSTRAINT fk_exp_category_society FOREIGN KEY(society_id) REFERENCES societies(id) ON DELETE RESTRICT ON UPDATE CASCADE)ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS society_vendors(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,society_id BIGINT UNSIGNED NOT NULL,vendor_name VARCHAR(180) NOT NULL,service_category VARCHAR(120) NOT NULL,contact_person VARCHAR(150) NULL,mobile VARCHAR(20) NULL,email VARCHAR(150) NULL,gstin VARCHAR(20) NULL,pan_number VARCHAR(20) NULL,address VARCHAR(500) NULL,status ENUM('ACTIVE','INACTIVE') NOT NULL DEFAULT 'ACTIVE',created_by BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_by BIGINT UNSIGNED NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,deleted_at TIMESTAMP NULL,UNIQUE KEY uk_vendor_name(society_id,vendor_name),KEY idx_vendor_service(society_id,service_category,status),CONSTRAINT fk_vendor_society FOREIGN KEY(society_id) REFERENCES societies(id) ON DELETE RESTRICT ON UPDATE CASCADE)ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS society_expenses(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,society_id BIGINT UNSIGNED NOT NULL,expense_number VARCHAR(50) NOT NULL,category_id BIGINT UNSIGNED NOT NULL,vendor_id BIGINT UNSIGNED NULL,expense_date DATE NOT NULL,invoice_number VARCHAR(100) NULL,description VARCHAR(1000) NOT NULL,amount DECIMAL(14,2) NOT NULL,paid_amount DECIMAL(14,2) NOT NULL DEFAULT 0,balance_amount DECIMAL(14,2) NOT NULL,status ENUM('DRAFT','SUBMITTED','APPROVED','REJECTED','PARTIALLY_PAID','PAID','CANCELLED') NOT NULL DEFAULT 'SUBMITTED',approval_note VARCHAR(500) NULL,approved_by BIGINT UNSIGNED NULL,approved_at DATETIME NULL,created_by BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uk_expense_number(society_id,expense_number),KEY idx_expense_status(society_id,status,expense_date),CONSTRAINT fk_expense_society FOREIGN KEY(society_id) REFERENCES societies(id) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT fk_expense_category FOREIGN KEY(category_id) REFERENCES expense_categories(id) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT fk_expense_vendor FOREIGN KEY(vendor_id) REFERENCES society_vendors(id) ON DELETE SET NULL ON UPDATE CASCADE)ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS expense_payments(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,society_id BIGINT UNSIGNED NOT NULL,expense_id BIGINT UNSIGNED NOT NULL,payment_date DATE NOT NULL,amount DECIMAL(14,2) NOT NULL,payment_mode ENUM('CASH','CHEQUE','NEFT','RTGS','UPI','CARD','ONLINE') NOT NULL,reference_number VARCHAR(100) NULL,notes VARCHAR(500) NULL,created_by BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,KEY idx_exp_payment(society_id,payment_date),CONSTRAINT fk_exp_payment_society FOREIGN KEY(society_id) REFERENCES societies(id) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT fk_exp_payment_expense FOREIGN KEY(expense_id) REFERENCES society_expenses(id) ON DELETE RESTRICT ON UPDATE CASCADE)ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS expense_sequences(society_id BIGINT UNSIGNED PRIMARY KEY,next_number BIGINT UNSIGNED NOT NULL DEFAULT 1,CONSTRAINT fk_expense_seq_society FOREIGN KEY(society_id) REFERENCES societies(id) ON DELETE RESTRICT ON UPDATE CASCADE)ENGINE=InnoDB;
INSERT INTO permissions(permission_name,permission_code,module_name,description,status)VALUES('View Expenses','society.expenses.view','expenses','View vendors and expenses','ACTIVE'),('Manage Expense Masters','society.expenses.manage','expenses','Manage categories, vendors and expense entries','ACTIVE'),('Approve Expenses','society.expenses.approve','expenses','Approve or reject submitted expenses','ACTIVE'),('Pay Expenses','society.expenses.pay','expenses','Record payments against approved expenses','ACTIVE')ON DUPLICATE KEY UPDATE status='ACTIVE';
INSERT INTO role_permissions(role_id,permission_id)SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.role_code IN('SUPER_ADMIN','SOCIETY_ADMIN','CHAIRMAN','SECRETARY','TREASURER')AND p.permission_code LIKE'society.expenses.%' ON DUPLICATE KEY UPDATE permission_id=VALUES(permission_id);INSERT INTO role_permissions(role_id,permission_id)SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.role_code='ACCOUNTANT' AND p.permission_code IN('society.expenses.view','society.expenses.manage','society.expenses.pay')ON DUPLICATE KEY UPDATE permission_id=VALUES(permission_id);
